      let users: any[] = [];
      if (fs.existsSync(usersFile)) {
        users = JSON.parse(fs.readFileSync(usersFile, "utf-8") || "[]");
      }

      const existingUser = users.find((u: any) => u.usernameKey === nameKey || u.username.toLowerCase() === nameKey);

